package com.vandorlabs.neoforge.builders;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.registries.RegisterEvent;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.IItemHandler;
@EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)
public final class NativeBuilderBindings {
 public static final Map<String,NativeBuilderCoreBlock> CORES=new LinkedHashMap<>();public static NativeBuilderPartBlock PART;public static BlockEntityType<NativeBuilderEntity> ENTITY;public static BlockEntityType<NativeBuilderPartEntity> PART_ENTITY;public static MenuType<NativeBuilderMenu> MENU;
 public static boolean enabled(){return Boolean.parseBoolean(System.getProperty("vandorlabs.builders","true"));}private static ResourceLocation id(String s){return ResourceLocation.fromNamespaceAndPath("vandorlabs",s);}
 @SubscribeEvent public static void register(RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var d:NativeBuilderDesigns.ALL){var b=new NativeBuilderCoreBlock(d,BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(5,6).requiresCorrectToolForDrops().noOcclusion().sound(SoundType.METAL));CORES.put(d.id(),b);h.register(id(d.block()),b);}PART=new NativeBuilderPartBlock(BlockBehaviour.Properties.of().strength(5,6).noOcclusion().noLootTable());h.register(id("constructor_part"),PART);});e.register(Registries.ITEM,h->{for(var d:NativeBuilderDesigns.ALL)h.register(id(d.block()),new BlockItem(CORES.get(d.id()),new Item.Properties()));});e.register(Registries.BLOCK_ENTITY_TYPE,h->{ENTITY=BlockEntityType.Builder.of(NativeBuilderEntity::new,CORES.values().toArray(Block[]::new)).build(null);PART_ENTITY=BlockEntityType.Builder.of(NativeBuilderPartEntity::new,PART).build(null);h.register(id("constructor_core"),ENTITY);h.register(id("constructor_part"),PART_ENTITY);NativeBuilderTransactions.register();});e.register(Registries.MENU,h->{MENU=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,buffer)->new NativeBuilderMenu(MENU,window,inventory,buffer.readBlockPos()));h.register(id("synthesis_tower"),MENU);});}
 @SubscribeEvent public static void creative(net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent e){if(enabled()&&e.getTabKey().location().equals(id("vandorlabs")))for(var b:CORES.values())e.accept(b);}
 @SubscribeEvent public static void capabilities(RegisterCapabilitiesEvent e){if(!enabled())return;e.registerBlockEntity(Capabilities.EnergyStorage.BLOCK,ENTITY,(t,side)->energy(t,t.getBlockPos(),side));e.registerBlockEntity(Capabilities.EnergyStorage.BLOCK,PART_ENTITY,(t,side)->energy(t.root(),t.getBlockPos(),side));e.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY,(t,side)->items(t,t.getBlockPos(),side));e.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PART_ENTITY,(t,side)->items(t.root(),t.getBlockPos(),side));}
 private static boolean port(NativeBuilderEntity t,BlockPos p,Direction side,boolean power){return t!=null&&t.available()&&t.formed()&&t.synthesis()&&side!=null&&p.equals(power?t.powerPort():t.itemPort())&&(side==t.facing().getOpposite()||side==Direction.DOWN||!power&&side==t.facing().getCounterClockWise());}
 private static net.neoforged.neoforge.energy.IEnergyStorage energy(NativeBuilderEntity t,BlockPos p,Direction side){if(!port(t,p,side,true))return null;return new net.neoforged.neoforge.energy.IEnergyStorage(){public int receiveEnergy(int n,boolean s){return port(t,p,side,true)?t.runtime.energy.receiveEnergy(n,s):0;}public int extractEnergy(int n,boolean s){return 0;}public int getEnergyStored(){return t.runtime.energy.getEnergyStored();}public int getMaxEnergyStored(){return t.runtime.energy.getMaxEnergyStored();}public boolean canReceive(){return port(t,p,side,true);}public boolean canExtract(){return false;}};}
 private static IItemHandler items(NativeBuilderEntity t,BlockPos p,Direction side){if(!port(t,p,side,false))return null;boolean input=side==t.facing().getOpposite();int physical=input?0:1;return new IItemHandler(){public int getSlots(){return 1;}public ItemStack getStackInSlot(int slot){return slot==0?t.stack(physical):ItemStack.EMPTY;}public int getSlotLimit(int slot){return slot==0?64:0;}public boolean isItemValid(int slot,ItemStack stack){return slot==0&&input&&t.canPlaceItem(0,stack);}public ItemStack insertItem(int slot,ItemStack stack,boolean simulate){if(!port(t,p,side,false)||!isItemValid(slot,stack))return stack;var existing=t.getItem(0);if(!existing.isEmpty()&&!ItemStack.isSameItemSameComponents(existing,stack))return stack;int n=Math.min(stack.getCount(),Math.min(64,stack.getMaxStackSize())-existing.getCount());if(n<=0)return stack;if(!simulate){if(existing.isEmpty())t.own(0,stack.copyWithCount(n));else{existing.grow(n);t.changed();}}return stack.copyWithCount(stack.getCount()-n);}public ItemStack extractItem(int slot,int n,boolean simulate){if(slot!=0||input||n<=0||!port(t,p,side,false))return ItemStack.EMPTY;var stack=t.getItem(1);return simulate?stack.copyWithCount(Math.min(n,stack.getCount())):t.removeItem(1,n);}};}
 public static NativeBuilderEntity ownerAt(Level l,BlockPos p){if(!NativeBuilderFormation.loaded(l,p))return null;var raw=l.getBlockEntity(p);return raw instanceof NativeBuilderEntity owner?owner:raw instanceof NativeBuilderPartEntity part?part.root():null;}
 public static boolean open(Player p,Level l,BlockPos pos){var owner=ownerAt(l,pos);if(owner==null||!owner.synthesis()||!owner.formed()||!owner.canUse(p)||MENU==null)return false;if(p instanceof ServerPlayer actor){actor.connection.send(owner.getUpdatePacket());actor.openMenu(new SimpleMenuProvider((window,inventory,ignored)->new NativeBuilderMenu(MENU,window,inventory,owner),owner.getBlockState().getBlock().getName()),buffer->buffer.writeBlockPos(owner.getBlockPos()));}return true;}
 public static boolean interact(Player p,Level l,BlockPos pos,InteractionHand hand){var t=ownerAt(l,pos);if(t==null||!t.canUse(p))return false;if(l.isClientSide)return true;if(!(p instanceof ServerPlayer actor))return false;try{if(!t.formed())return NativeBuilderTransactions.request(t,actor,true);if(p.isShiftKeyDown())return NativeBuilderTransactions.request(t,actor,false);if(t.synthesis()&&mount(t,p,hand))return true;return open(p,l,pos);}catch(IllegalArgumentException refused){p.displayClientMessage(net.minecraft.network.chat.Component.literal(refused.getMessage()),true);return true;}}
 private static Vec3 world(NativeBuilderEntity t,double x,double y,double z){var origin=t.getBlockPos().subtract(t.pivot());var d=t.design();return switch(t.facing()){case EAST->new Vec3(origin.getX()+d.depth()-z,origin.getY()+y,origin.getZ()+x);case SOUTH->new Vec3(origin.getX()+d.width()-x,origin.getY()+y,origin.getZ()+d.depth()-z);case WEST->new Vec3(origin.getX()+z,origin.getY()+y,origin.getZ()+d.width()-x);default->new Vec3(origin.getX()+x,origin.getY()+y,origin.getZ()+z);};}
 private static boolean hit(NativeBuilderEntity t,Player p,double x,double y,double z,double w,double h){var center=world(t,x,y,z);var normal=Vec3.atLowerCornerOf(t.facing().getNormal());var start=p.getEyePosition();var delta=p.getLookAngle().scale(p.blockInteractionRange());double div=delta.dot(normal);if(div>=-1e-8)return false;double time=center.subtract(start).dot(normal)/div;if(time<0||time>1)return false;var local=start.add(delta.scale(time)).subtract(center);var u=Vec3.atLowerCornerOf(t.facing().getClockWise().getNormal());return Math.abs(local.dot(u))<=w/2+.035&&Math.abs(local.y)<=h/2+.035;}
 private static boolean mount(NativeBuilderEntity t,Player p,InteractionHand hand){var held=p.getItemInHand(hand);if(hit(t,p,.67,.56,0,.72,.72)){if(t.getItem(2).isEmpty()&&com.vandorlabs.neoforge.rack.NativeBatteryModule.valid(held)){t.own(2,held.copyWithCount(1));held.shrink(1);return true;}if(held.isEmpty()&&!t.getItem(2).isEmpty()){p.setItemInHand(hand,t.removeItemNoUpdate(2));return true;}}
  if(hit(t,p,.68,1.5,.35,.375,.375)){if(t.getItem(3).isEmpty()&&t.canPlaceItem(3,held)){t.own(3,held.copyWithCount(1));held.shrink(1);return true;}if(held.isEmpty()&&!t.getItem(3).isEmpty()){var stack=t.removeItemNoUpdate(3);if(!p.getInventory().add(stack))p.drop(stack,false);return true;}}
  if(!t.getItem(1).isEmpty()){var a=world(t,1,2.125,1.125);var b=world(t,2,3.125,2.125);var box=new AABB(a,b);if(box.clip(p.getEyePosition(),p.getEyePosition().add(p.getLookAngle().scale(p.blockInteractionRange()))).isPresent()){var stack=t.removeItem(1,1);if(!p.getInventory().add(stack))p.drop(stack,false);return true;}}return false;}
 private NativeBuilderBindings(){}
}
